<?php require __DIR__.'/includes/bootstrap.php';$from=trim($_GET['origine']??'');$to=trim($_GET['destination']??'');$date=$_GET['date']??'';$kind=$_GET['type_transport']??'';$sql="SELECT s.*,r.origine,r.destination,r.type_transport,r.compagnie,r.prix FROM trips_schedule s JOIN routes r ON r.id=s.route_id WHERE r.actif=1 AND s.places_restantes>0 AND s.date_depart>=CURDATE()";$args=[];foreach(['origine'=>$from,'destination'=>$to] as $k=>$v)if($v!==''){$sql.=' AND r.'.$k.' LIKE ?';$args[]='%'.$v.'%';}if($date){$sql.=' AND s.date_depart=?';$args[]=$date;}if(in_array($kind,['bus','avion'],true)){$sql.=' AND r.type_transport=?';$args[]=$kind;}$sql.=' ORDER BY s.date_depart,s.heure_depart';$st=$pdo->prepare($sql);$st->execute($args);$rows=$st->fetchAll();$title='Billets de voyage';require __DIR__.'/includes/header.php';?>
<section class="max-w-7xl mx-auto px-4 pb-12"><div class="page-heading"><p class="page-eyebrow">Bus & vols · Départs disponibles</p><h1 class="page-title">Trouvez votre prochain trajet</h1><p class="page-subtitle">Comparez les départs et réservez votre place en quelques étapes.</p></div>
<form class="booking-search" method="get"><div><label>Départ de</label><input name="origine" value="<?=e($from)?>" placeholder="Douala" required></div><div><label>Destination</label><input name="destination" value="<?=e($to)?>" placeholder="Yaoundé" required></div><div><label>Date de départ</label><input type="date" name="date" value="<?=e($date)?>"></div><div><label>Transport</label><select name="type_transport"><option value="">Tous</option><option value="bus" <?=$kind==='bus'?'selected':''?>>Bus</option><option value="avion" <?=$kind==='avion'?'selected':''?>>Avion</option></select></div><button class="btn">Rechercher</button></form>
<div class="list-layout"><aside class="filter-panel"><h2>Voyagez sereinement</h2><div class="filter-group"><span class="pill">Places disponibles</span><p class="text-sm text-slate-600 mt-3">Les horaires et places restantes sont mis à jour à partir des départs publiés par les compagnies.</p></div><div class="filter-group"><strong class="text-sm">Paiement local</strong><p class="text-sm text-slate-600 mt-2">Orange Money, MTN Mobile Money et carte bancaire (simulation).</p></div><div class="filter-group"><strong class="text-sm">Besoin d'un séjour ?</strong><a href="/hotels.php" class="text-teal-800 underline text-sm block mt-2">Rechercher un hôtel</a></div></aside>
<div><div class="result-topline"><p class="result-count"><strong><?=count($rows)?></strong> départ<?=count($rows)===1?'':'s'?> disponible<?=count($rows)===1?'':'s'?></p><span class="text-sm text-slate-500">Prix par billet · FCFA</span></div><div class="result-list"><?php foreach($rows as $t):?><article class="journey-card"><div><p class="journey-operator"><?=e($t['type_transport'])?> · <?=e($t['compagnie'])?></p><h2 class="journey-route"><?=e($t['origine'])?> <span class="text-orange-500">→</span> <?=e($t['destination'])?></h2><div class="journey-meta"><span>◷ <?=date('d/m/Y',strtotime($t['date_depart']))?> · <?=substr($t['heure_depart'],0,5)?></span><span>♧ <?=$t['places_restantes']?> places restantes</span></div></div><div class="journey-book"><strong><?=money($t['prix'])?></strong><form action="/checkout.php" method="get"><input type="hidden" name="type" value="billet"><input type="hidden" name="schedule_id" value="<?=$t['id']?>"><label class="sr-only" for="nb-<?=$t['id']?>">Nombre de billets</label><select id="nb-<?=$t['id']?>" name="nb" class="w-full mt-2"><?php for($i=1;$i<=min(6,(int)$t['places_restantes']);$i++):?><option value="<?=$i?>"><?=$i?> billet<?=$i>1?'s':''?></option><?php endfor;?></select><button class="btn">Choisir ce départ</button></form></div></article><?php endforeach;?><?php if(!$rows):?><div class="empty-state"><strong class="text-slate-800">Aucun départ pour cette recherche</strong><p class="mt-2">Modifiez votre itinéraire ou choisissez une autre date.</p><a class="btn mt-4" href="/billets.php">Voir tous les départs</a></div><?php endif;?></div></div></div></section><?php require __DIR__.'/includes/footer.php';?>
